  for (let j = 0; j < sub; j++) {
    const su = ((i - i0 - 1) * DS + (j + 0.5) * hs);
    const k = kap0(su / scale) / scale;
    const thm = TH + k * hs / 2;
    X += Math.cos(thm) * hs; Y += Math.sin(thm) * hs; TH += k * hs;
  }
  tx[i] = X; ty[i] = Y; tth[i] = TH; tk[i] = kap0(((i - i0) * DS) / scale) / scale;
}
const S0 = -APRON;
const sAt = i => S0 + i * DS;
function sample(sq) {
  const f = clamp((sq - S0) / DS, 0, N - 1.000001); const i = Math.floor(f), u = f - i;
  return { x: tx[i] + (tx[i + 1] - tx[i]) * u, y: ty[i] + (ty[i + 1] - ty[i]) * u, th: tth[i] + (tth[i + 1] - tth[i]) * u, k: tk[i] + (tk[i + 1] - tk[i]) * u };
}
// spatial grid of nearest-sample hints for closest-point queries
const GX0 = -APRON - 3, GX1 = 15, GY0 = -3, GY1 = 23, GC = 0.5;
const GW = Math.ceil((GX1 - GX0) / GC), GH = Math.ceil((GY1 - GY0) / GC);
const hint = new Int32Array(GW * GH);
for (let gy = 0; gy < GH; gy++) for (let gx = 0; gx < GW; gx++) {
  const cx = GX0 + (gx + 0.5) * GC, cy = GY0 + (gy + 0.5) * GC; let best = 1e18, bi = 0;
  for (let i = 0; i < N; i += 2) { const dx = tx[i] - cx, dy = ty[i] - cy, d2 = dx * dx + dy * dy; if (d2 < best) { best = d2; bi = i; } }
  hint[gy * GW + gx] = bi;
}
const SMAX = L;
// closest point on the profile curve to (px,py); returns s, the point, heading and signed normal distance
function closest(px, py) {
  const gx = Math.floor((px - GX0) / GC), gy = Math.floor((py - GY0) / GC);
  let sq;
  if (gx >= 0 && gy >= 0 && gx < GW && gy < GH) sq = sAt(hint[gy * GW + gx]);
  else return null;
  let smp = null;
  for (let it = 0; it < 4; it++) {
    smp = sample(sq);
    const t0 = Math.cos(smp.th), t1 = Math.sin(smp.th);
    const dx = px - smp.x, dy = py - smp.y;
    const along = dx * t0 + dy * t1;
    const dn = -dx * t1 + dy * t0;
    const step = along / Math.max(0.2, 1 - smp.k * dn);
    const ns = clamp(sq + step, S0, SMAX);
    if (Math.abs(ns - sq) < 1e-5) { sq = ns; break; }
    sq = ns;
  }
