// RAMP GEOMETRY — profile defined by a continuous curvature function κ(s)
// (C2-smooth blends, so heading and curvature are continuous: no kinks).
// Profile lies in the world XY plane, x toward the ramp, y up, centred on z = 0.
// ============================================================================
const RAMP = (() => {
  const W = 6.0, T = 0.42, APRON = 14, LIP_DEG = 115;
  const ss = (a, b, x) => { const t = clamp((x - a) / (b - a), 0, 1); return t * t * t * (t * (t * 6 - 15) + 10); };
  // Unscaled curvature design: tight foot, long gently-leaning wall, tighter hook at the top.
  const k1 = 1 / 7, k2 = 1 / 20, k3 = 1 / 12, a = 3.5, b = 10.5, c = 13, d = 20, e = 24;
