const code=files.map(f=>fs.readFileSync('src/'+f,'utf8')).join('\n')+'\nreturn {createSim,RAMP,PHASES};';
const M=new Function(code)();
for (const [name,cfg] of [['lowdf',{fanKg:1500}],['thrust0',{thrustKN:0}],['slow',{powerKW:78}]]){
