  while(!sim.done){ sim.step(); if(!firstBreak && sim.broken.length) firstBreak={t:+sim.t.toFixed(2),p:[sim.car.p.x,sim.car.p.y,sim.car.p.z].map(v=>+v.toFixed(1))}; }
